//*****************************************************************************
//
// File Name        : 'Process Response'
// Title            : Process Fan Control Response
// Author           : http://www.prochazka.zde.cz
// Created          : 16-07-2024, 04:40
// Revised          : 14-12-2025, 13:15
// Version          : 1.1
// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Tento skript zpracovává odpověď z HTTP requestu na ovládání ventilátorů
// a zobrazuje aktuální fyzický stav obou ventilátorů.
//
// VSTUPNÍ DATA:
// - msg.statusCode - HTTP status code (musí být 200)
// - msg.responseUrl - URL requestu obsahující IP a stav (turn=on/off)
// - msg.payload - JSON odpověď ze zařízení
//
// VÝSTUPNÍ DATA:
// - msg.payload.indicator - identifikátor ventilátoru ('mptt-fan' nebo 'changer-fan')
// - msg.payload.status - stav ventilátoru ('on' nebo 'off')
// - msg.payload.topic - téma zprávy ('update-indicator')
//
// ROZPOZNÁNÍ ZAŘÍZENÍ:
// - IP 192.168.11.7 = MPTT ventilátor
// - IP 192.168.11.9 = CHANGER ventilátor
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2025 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = false;  // Nastavte na true pro zapnutí debug zpráv

// Kontrola statusCode
if (msg.statusCode !== 200) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Chyba: HTTP " + (msg.statusCode || "bez odpovědi")
    });
    return null; // Pokud není statusCode 200, vrátíme null a ukončíme zpracování
}

const response = JSON.parse(msg.payload);
let sURL = msg.responseUrl;

// Ruční zpracování URL pro získání IP adresy a hodnoty 'turn'
let ipAddress = sURL.split('/')[2];
let turnValue = sURL.includes('turn=on') ? 'on' : 'off';

let indicatorMsg = {};
let sStatusText = "";

// Debugging vstupních dat
if (debug) {
    node.warn("=== PROCESS RESPONSE DEBUG ===");
    node.warn("sURL: " + sURL);
    node.warn("ipAddress: " + ipAddress);
    node.warn("turnValue: " + turnValue);
}

// Inicializace nebo načtení kontextových proměnných pro oba ventilátory
let mpttFanStatus = context.get('mpttFanStatus') || 'unknown';
let changerFanStatus = context.get('changerFanStatus') || 'unknown';

// Aktualizace příslušného ventilátoru
if (ipAddress === '192.168.11.7') {
    mpttFanStatus = turnValue;
    context.set('mpttFanStatus', mpttFanStatus);
    indicatorMsg = { indicator: 'mptt-fan', status: turnValue, topic: 'update-indicator' };
} else if (ipAddress === '192.168.11.9') {
    changerFanStatus = turnValue;
    context.set('changerFanStatus', changerFanStatus);
    indicatorMsg = { indicator: 'changer-fan', status: turnValue, topic: 'update-indicator' };
}

// Sestavení textu pro status
let mpttText = mpttFanStatus === 'on' ? '🟢 MPTT' : (mpttFanStatus === 'off' ? '⚪ MPTT' : '⚫ MPTT');
let changerText = changerFanStatus === 'on' ? '🟢 CHANGER' : (changerFanStatus === 'off' ? '⚪ CHANGER' : '⚫ CHANGER');
sStatusText = mpttText + " | " + changerText;

// Určení barvy pro status (pokud alespoň jeden běží = zelená)
let statusFill = "grey";
if (mpttFanStatus === 'on' || changerFanStatus === 'on') {
    statusFill = "green";
}
if (mpttFanStatus === 'unknown' || changerFanStatus === 'unknown') {
    statusFill = "yellow";
}

// Zobrazení stavu obou ventilátorů pod nodem
node.status({
    fill: statusFill,
    shape: "dot",
    text: sStatusText
});

// Debug výpis
if (debug) {
    node.warn("MPTT Fan Status: " + mpttFanStatus);
    node.warn("CHANGER Fan Status: " + changerFanStatus);
    node.warn("Status Text: " + sStatusText);
    node.warn("=============================");
}

return { payload: indicatorMsg };

//*****************************************************************************
//
// File Name        : N/A
// Title            : MPTT Cooling Control with Hysteresis
// Author           : http://www.prochazka.zde.cz
// Created          : 16-07-2024, 04:40
// Revised          : 24-06-2026
// Version          : 1.3
// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Řídí zapínání/vypínání ventilátoru MPTT s hysterezí pro zabránění
// častého přepínání (fluktuace).
//
// ZAPNUTÍ:  musí přijít nWaitStartLoop× po sobě požadavek na zapnutí
// VYPNUTÍ:  musí přijít nWaitLoop× po sobě požadavek na vypnutí
// Opačný požadavek mezitím vynuluje příslušný čítač.
//
// NASTAVENÍ:
//  - nWaitLoop = 10      (cyklů pro vypnutí)
//  - nWaitStartLoop = 2  (cyklů pro zapnutí)
//  - debug = true/false
//
// VSTUPNÍ DATA:
//  - msg.payload._url_m - URL pro ovládání relé
//  - msg.payload.nTurn  - požadavek na stav (1/true=zapnout, 0/false=vypnout)
//
// VÝSTUPNÍ DATA:
//  - msg.payload - URL, odešle se POUZE při změně stavu
//
// (c) 1997 - 2026 hacesoft. GPL.
//*****************************************************************************

// Debugging flag
const debug = false;

// KONFIGURACE
const nWaitLoop = 10;       // Kolik cyklů čekat pro VYPNUTÍ
const nWaitStartLoop = 2;   // Kolik cyklů čekat pro ZAPNUTÍ

// Inicializace kontextových proměnných
let nCopyOnChange_url_m = context.get('nCopyOnChange_url_m') || "";
let nWaitLoopOff_m = context.get('nWaitLoopOff_m') || 0;
let nWaitLoopOn_m = context.get('nWaitLoopOn_m') || 0;
let bVentilatorState = context.get('bVentilatorState_m') || false;

// Načtení vstupních dat
const _url_m = msg.payload && msg.payload._url_m ? msg.payload._url_m : "";
const nTurn = msg.payload && msg.payload.nTurn !== undefined ? msg.payload.nTurn : false;

let sStatusText = "";
let bSendCommand = false;

// Logika řízení ventilátoru
if (nTurn == true) {
    // Požadavek na ZAPNUTÍ
    nWaitLoopOn_m += 1;
    nWaitLoopOff_m = 0;

    if (nWaitLoopOn_m >= nWaitStartLoop) {
        if (bVentilatorState == false) {
            bVentilatorState = true;
            bSendCommand = true;
            context.set('nCopyOnChange_url_m', _url_m);
        }
        sStatusText = "🟢 BĚŽÍ";
        nWaitLoopOn_m = 0;
    } else {
        if (bVentilatorState) {
            sStatusText = "🟢 BĚŽÍ (zap " + nWaitLoopOn_m + "/" + nWaitStartLoop + ")";
        } else {
            sStatusText = "⚪ stojí, čeká na zap (" + nWaitLoopOn_m + "/" + nWaitStartLoop + ")";
        }
    }

} else {
    // Požadavek na VYPNUTÍ
    nWaitLoopOff_m += 1;
    nWaitLoopOn_m = 0;

    if (nWaitLoopOff_m >= nWaitLoop) {
        if (bVentilatorState == true) {
            bVentilatorState = false;
            bSendCommand = true;
            context.set('nCopyOnChange_url_m', _url_m);
        }
        sStatusText = "⚪ STOJÍ";
        nWaitLoopOff_m = 0;
    } else {
        if (bVentilatorState) {
            sStatusText = "🟢 BĚŽÍ, čeká na vyp (" + nWaitLoopOff_m + "/" + nWaitLoop + ")";
        } else {
            sStatusText = "⚪ stojí (vyp " + nWaitLoopOff_m + "/" + nWaitLoop + ")";
        }
    }
}

// Uložit čítače do kontextu
context.set('nWaitLoopOff_m', nWaitLoopOff_m);
context.set('nWaitLoopOn_m', nWaitLoopOn_m);
context.set('bVentilatorState_m', bVentilatorState);

// Zobrazení stavu pod nodem
node.status({
    fill: bVentilatorState ? "green" : "grey",
    shape: "dot",
    text: sStatusText
});

// Debug výpisy
if (debug) {
    node.warn("=== VENTILÁTOR MPTT CONTROL DEBUG ===");
    node.warn("Požadavek (nTurn): " + (nTurn ? "ZAPNOUT" : "VYPNOUT"));
    node.warn("Stav ventilátoru: " + (bVentilatorState ? "BĚŽÍ" : "VYPNUTO"));
    node.warn("Čítač zapnutí: " + nWaitLoopOn_m + "/" + nWaitStartLoop);
    node.warn("Čítač vypnutí: " + nWaitLoopOff_m + "/" + nWaitLoop);
    node.warn("Odesílám příkaz: " + (bSendCommand ? "ANO" : "NE"));
    node.warn("URL: " + _url_m);
    node.warn("=====================================");
}

// Odeslat zprávu pouze při změně stavu
if (bSendCommand) {
    msg.payload = _url_m;
    return msg;
} else {
    return null;
}

