//*****************************************************************************
//
// File Name        : 'Chlazeni_CHANGERs'
// Title            : Cooling of Changers in the Rack
// Author           : http://www.prochazka.zde.cz
// Created          : 21-10-2023, 11:00
// Revised          : 24-06-2026
// Version          : 3.0
// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Chlazení měniče se řídí podle toho, zda měnič reálně KONVERTUJE energii.
// Pouze tehdy se měnič zahřívá a je třeba chladit.
//
// CHLAZENÍ ON (měnič konvertuje):
//  1) Baterie se vybíjí (DC→AC do baráku/gridu)
//       nBattery_Power < -trigger
//  2) Baterie se nabíjí z gridu (AC→DC), FV na to nestačí
//       (nBattery_Power - pvPower) > trigger
//  3) FV přetoky do gridu (DC→AC), FV vyrábí víc, než jde do baterie
//       (pvPower - nBattery_Power) > trigger
//
// CHLAZENÍ OFF (měnič NEkonvertuje):
//  - Baterie se nabíjí čistě ze slunce (FV ≈ nabíjení) → bez měniče
//  - Klid (baterie i FV ~0)
//  - POZN.: odběr z gridu do baráku bez činnosti baterie/FV NEznamená
//    práci měniče (typicky v noci/zimě, baterie vybitá) → nechladit
//
// NASTAVENÍ:
//  - n_trigger = 600W (jednotný práh detekce práce měniče)
//  - debug = true/false
//
// VSTUPNÍ DATA:
//  - msg.payload._general_stop (true/false) - nouzové vypnutí
//  - global.get("pvPower")          - výroba FV [W] (už ošetřená)
//  - registr 842 Battery Power      - výkon baterie [W], surově unsigned 0..65535
//                                     (kladné=nabíjení, záporné=vybíjení po konverzi)
//
// VÝSTUPNÍ DATA:
//  - msg.payload._url_ch            - URL pro ovládání relé
//  - msg.payload.sTurn              - "on CHANGER" / "off CHANGER"
//  - msg.payload.nTurn              - binární stav (1/0)
//  - msg.payload.pvPower            - hodnota FV
//  - msg.payload.nBattery_Power     - hodnota baterie (signed)
//
// (c) 1997 - 2026 hacesoft. GPL.
//*****************************************************************************

// Debugging flag
const debug = false;

// Definice globálních funkcí
const fSendUrl = global.get('fSendUrl');
const nConvertSignetUnsignet = global.get('nConvertSignetUnsignet');

if (fSendUrl && nConvertSignetUnsignet) {

    const nRelayNumber = 0;
    const sIpAddress = "192.168.11.9";
    let sTurn = "off";
    let nTurn = 0;
    const n_trigger = 600;   // jednotný práh pro detekci práce měniče [W]
    let _url = "";
    let sStatusText = "";

    // Vstupní data
    const _general_stop = msg.payload._general_stop;
    const pvPower = global.get("pvPower") || 0;   // výroba FV [W], už ošetřená

    // Battery Power (System) - registr 842, surově unsigned 0..65535
    let nBattery_Power_raw = (parseFloat(msg.payload.nBattery_Power) || global.get('nBattery_Power')) ?? 0;
    let nBattery_Power = nConvertSignetUnsignet(nBattery_Power_raw);
    // Po konverzi: kladné = nabíjení, záporné = vybíjení

    // Sanity check - výkon baterie reálně nepřesáhne ±~15kW
    if (Math.abs(nBattery_Power) > 30000) {
        node.warn("PODEZŘELÁ hodnota baterie po konverzi: " + nBattery_Power + "W (raw: " + nBattery_Power_raw + ")");
    }

    if (_general_stop == true) {
        sTurn = "off";
        nTurn = 0;
        sStatusText = "General STOP aktivní";
    } else {
        let bCooling = false;

        // Kolik nabíjení baterie NEpokrývá FV → teče z gridu přes měnič (AC→DC)
        const nChargeFromGrid = nBattery_Power - pvPower;
        // Kolik FV přebývá nad rámec nabíjení baterie → teče do gridu přes měnič (DC→AC)
        const nPvSurplusToGrid = pvPower - nBattery_Power;

        // Podmínka 1: Baterie se vybíjí (DC→AC)
        if (nBattery_Power < -n_trigger) {
            bCooling = true;
            sStatusText = "ON - Baterie vybíjí: " + nBattery_Power + "W";
        }
        // Podmínka 2: Nabíjení z gridu (AC→DC), FV nestačí
        else if (nChargeFromGrid > n_trigger) {
            bCooling = true;
            sStatusText = "ON - Nabíjení z gridu: " + Math.round(nChargeFromGrid) +
                          "W (Bat:" + nBattery_Power + ", FV:" + pvPower + ")";
        }
        // Podmínka 3: FV přetoky do gridu (DC→AC)
        else if (nPvSurplusToGrid > n_trigger) {
            bCooling = true;
            sStatusText = "ON - FV přetok do gridu: " + Math.round(nPvSurplusToGrid) +
                          "W (FV:" + pvPower + ", Bat:" + nBattery_Power + ")";
        }
        // Jinak měnič nekonvertuje
        else {
            bCooling = false;
            if (pvPower > n_trigger && nBattery_Power > 0) {
                sStatusText = "OFF - Nabíjení ze slunce (FV:" + pvPower +
                              ", Bat:+" + nBattery_Power + ")";
            } else {
                sStatusText = "OFF - Klid (FV:" + pvPower + ", Bat:" + nBattery_Power + ")";
            }
        }

        sTurn = bCooling ? "on" : "off";
        nTurn = bCooling ? 1 : 0;
    }

    // Vytvořit URL na základě hodnoty sTurn
    _url = fSendUrl(sIpAddress, nRelayNumber, sTurn);

    // Nastavit payload zprávy
    msg.payload = {
        _url_ch: _url,
        sTurn: sTurn + " CHANGER",
        nTurn: nTurn,
        pvPower: pvPower,
        nBattery_Power: nBattery_Power,
    };

    // Zobrazení stavu pod nodem
    node.status({
        fill: nTurn === 1 ? "green" : "grey",
        shape: "dot",
        text: sStatusText
    });

    // Debug výpisy
    if (debug) {
        node.warn("=== COOLING CHANGER DEBUG ===");
        node.warn("FV (pvPower): " + pvPower + "W");
        node.warn("Baterie RAW (unsigned): " + nBattery_Power_raw + "W");
        node.warn("Baterie CONVERTED (signed): " + nBattery_Power + "W");
        node.warn("Chlazení: " + sTurn);
        node.warn("Status: " + sStatusText);
        node.warn("URL: " + _url);
        node.warn("============================");
    }
} else {
    node.error("Globální funkce nebyly nalezeny. <- FORM CHLAZENI FVE -- CHANGER");
    node.status({
        fill: "red",
        shape: "ring",
        text: "Chyba: Globální funkce nenalezeny"
    });
}
return msg;

