// Target Platform  : Node-RED
//
// MANUÁL:
// -------
// Tento skript řídí chlazení MPPT trackerů na základě jejich výkonu.
//
// CHLAZENÍ SE ZAPNE (sTurn = "on") když:
// - MPPT výkon (pvPower) je >= 900W (n_trigger_MPTT)
//   Příklad: pvPower 950W → Chlazení ON
//
// CHLAZENÍ SE VYPNE (sTurn = "off") když:
// - MPPT výkon (pvPower) je < 900W
//   Příklad: pvPower 850W → Chlazení OFF
// - General STOP je aktivní (_general_stop = true)
//
// NASTAVENÍ:
// - n_trigger_MPTT = 900W (trigger pro zapnutí chlazení)
// - debug = true/false (zapne/vypne debug zprávy)
//
// VSTUPNÍ DATA:
// - msg.payload._general_stop (true/false) - nouzové vypnutí
// - global.get("pvPower") - aktuální výkon MPPT v W
//
// VÝSTUPNÍ DATA:
// - msg.payload._url_m - URL pro ovládání relé
// - msg.payload.pvPower - hodnota MPPT
// - msg.payload.nTurn - binární stav (1/0)
// - msg.payload.sTurn - textový stav ("on MPTT" / "off MPTT")
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2025 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = false;  // Nastavte na true pro zapnutí debug zpráv

//definice globalních funkci
const fSendUrl = global.get('fSendUrl');

if (fSendUrl) {
    const nRelayNumber = 0;
    const sIpAddress = "192.168.11.7";
    let sTurn = "off";  // Výchozí hodnota
    let nTurn = 0;  // Výchozí hodnota
    let n_trigger_MPTT = 710; // defaultní hodnota triggeru
    let _url = "";
    let sStatusText = "";

    //Načtení vstupních dat
    const _general_stop = msg.payload._general_stop;// general stop

    // Načteni globálních dat
    const pvPower = global.get("pvPower") || 0; // Hodnota z registru 819 

    if (_general_stop == true){
        sTurn = "off";
        nTurn = 0;
        sStatusText = "General STOP aktivní";
    } else {
        // Zkontroluj, zda pvPower je větší nebo rovno n_trigger_MPTT a nastav sTurn podle toho
        if (pvPower >= n_trigger_MPTT) {
            sTurn = "on";
            nTurn = 1;
            sStatusText = "ZAPNUTO - MPPT: " + pvPower + "W (>=" + n_trigger_MPTT + "W)";
        } else {
            sTurn = "off";
            nTurn = 0;
            sStatusText = "VYPNUTO - MPPT: " + pvPower + "W (<" + n_trigger_MPTT + "W)";
        }
    }

    // Vytvořit URL na základě hodnoty sTurn
    _url = fSendUrl(sIpAddress, nRelayNumber, sTurn);

    // Nastavit payload zprávy
    msg.payload = {
        _url_m: _url,
        pvPower: pvPower,
        nTurn: nTurn,
        sTurn: sTurn + " MPTT"
    };

    // Zobrazení stavu přímo pod nodem (viditelné v editoru)
    node.status({
        fill: nTurn === 1 ? "green" : "grey",
        shape: "dot",
        text: sStatusText
    });

    // Debug výpisy
    if (debug) {
        node.warn("=== COOLING MPTT DEBUG ===");
        node.warn("MPPT (pvPower): " + pvPower + "W");
        node.warn("Trigger: " + n_trigger_MPTT + "W");
        node.warn("Chlazení: " + sTurn);
        node.warn("General STOP: " + (_general_stop ? "ANO" : "NE"));
        node.warn("URL: " + _url);
        node.warn("==========================");
    }
} else {
    node.error("Globální funkce nebyly nalezeny. <- FORM CHLAZENI FVE -- MPTT");
    node.status({
        fill: "red",
        shape: "ring",
        text: "Chyba: Globální funkce nenalezeny"
    });
}
return msg;
